!function(){"use strict";app.directive("btnDataAdicionalArticulo",(function(modalService,nombreModal){return{restrict:"A",scope:{entity:"=",getDataEtiqueta:"&",datosAdicionales:"="},link:function(scope,element,attrs){element.on("click",(async function(){if(!Number.isInteger(scope.entity.cantidad))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"El valor de la cantidad del artículo tiene que ser un número entero!"});let{fileCtrl:fileCtrl,controller:controller,template:template}=nombreModal.compra.MODAL_DATO_ADICIONAL_ARTICULO,ctrl=(await import(fileCtrl))[controller],modalRef;modalService.openModalCustom({controller:ctrl,template:template,size:"lg",params:{entity:scope.entity,datosAdicionales:scope.datosAdicionales},isRenderRazorPartial:!0}).result.then((function(result){if("object"==typeof result)if(scope.datosAdicionales.some(item=>item.idArticulo===scope.entity.idArticulo))for(let label of scope.datosAdicionales)label.idArticulo===scope.entity.idArticulo&&(label.adicionales=result.data);else scope.datosAdicionales.push({idArticulo:scope.entity.idArticulo,idEtiqueta:scope.entity.etiquetas[0].idEtiqueta,adicionales:result.data})}))}))}}}))}(window.angular);